import xml.etree.ElementTree as ET
from pathlib import Path

NS = {'hp':'http://www.hancom.co.kr/hwpml/2010/HWPML'}
ET.register_namespace('hp', NS['hp'])

def p_text(p):
    return ''.join(p.itertext())

def set_p_text_single_run(p, new_text):
    # Find all hp:t descendants
    ts = list(p.findall('.//hp:t', NS))
    if not ts:
        return False
    # Set first and blank rest
    ts[0].text = new_text
    for t in ts[1:]:
        t.text = ''
    return True

def remove_layout_cache(p):
    removed = []
    # remove any descendants whose localname matches cache-ish tokens
    cache_tokens = {'linesegarray','lineseg','linesegArray','lineSegArray','lineSeg','parameterset','parameterSet'}
    # Build parent map
    parent = {c: par for par in p.iter() for c in list(par)}
    for el in list(p.iter()):
        tag = el.tag
        if not isinstance(tag,str) or '}' not in tag:
            continue
        local = tag.split('}',1)[1]
        if local in cache_tokens:
            par = parent.get(el)
            if par is not None:
                par.remove(el)
                removed.append(local)
    return removed

def replace_in_section(path: Path, replacements: list[tuple[str,str]]):
    tree = ET.parse(path)
    root = tree.getroot()
    modified_p_ids = set()

    for p in root.findall('.//hp:p', NS):
        original = p_text(p)
        new = original
        for old, newv in replacements:
            if old in new:
                new = new.replace(old, newv)
        if new != original:
            # Update paragraph text (keep structure) by writing into first hp:t and blanking rest
            ok = set_p_text_single_run(p, new)
            if ok:
                modified_p_ids.add(p.get('id'))
            else:
                # no text nodes found; skip
                pass

    # follow-up specific replacements in section1 only handled elsewhere

    # remove layout cache in modified paragraphs
    for p in root.findall('.//hp:p', NS):
        if p.get('id') in modified_p_ids:
            remove_layout_cache(p)

    tree.write(path, encoding='UTF-8', xml_declaration=True)
    return modified_p_ids

def replace_followups(path: Path, followups: list[str]):
    tree = ET.parse(path)
    root = tree.getroot()
    # Find p ids 41-43 by current text starting with '1.' etc
    modified = set()
    candidates = []
    for p in root.findall('.//hp:p', NS):
        txt = p_text(p).strip()
        if txt.startswith('1.') or txt.startswith('2.') or txt.startswith('3.'):
            candidates.append((p, txt))
    # Choose the three with exact old pattern if present; else first three sorted by id
    # We'll sort by numeric id
    def pid_num(p):
        try:
            return int(p.get('id'))
        except:
            return 10**9
    candidates.sort(key=lambda pt: pid_num(pt[0]))
    # Take first three
    for idx,(p,txt) in enumerate(candidates[:3]):
        new_text = f"{idx+1}. {followups[idx]}"
        set_p_text_single_run(p, new_text)
        modified.add(p.get('id'))
        remove_layout_cache(p)

    tree.write(path, encoding='UTF-8', xml_declaration=True)
    return modified

repls = [
    ('Northwind Retail', 'Asteron Commerce'),
    ('이전담당자', '한예진'),
    ('2025-04-01 ~ 2025-04-15', '2026-08-12 ~ 2026-08-26'),
    ('Standard-18M', 'Priority-24M'),
    ('ops-old@northwind.example', 'renewals-escalation@asteron.example'),
    ('기존 메모를 새 메모로 바꾸세요.', '가격 검토가 끝날 때까지 할인 문구를 외부에 공유하지 마세요.'),
]

sec0 = Path('/tmp/hwpx_work/Contents/section0.xml')
sec1 = Path('/tmp/hwpx_work/Contents/section1.xml')

m0 = replace_in_section(sec0, repls)
m1 = replace_in_section(sec1, repls)

followups = [
    '보안 검토 완료 일정을 고객과 다시 확인',
    '결재 라인에 최신 가격 밴드를 반영',
    '갱신 주간에 에스컬레이션 연락처를 온콜로 고정',
]
mf = replace_followups(sec1, followups)

print('modified sec0 p ids', sorted(m0, key=lambda x:int(x)))
print('modified sec1 p ids', sorted(m1|mf, key=lambda x:int(x)))
